mapper.select:
SELECT
    vm.record_id AS recordId,
    vm.type AS actionType,
    vm.status AS status,
    var.overall_score AS overallScore,
    var.grade AS grade,
    vm.skeleton_video_name AS skeletonVideoName,
    vm.create_time AS createTime,
    vm.update_time AS updateTime,
    var.max_bat_speed_km_h AS maxBatSpeedKmH,
    var.left_speed_km_h AS leftSpeedKmH,
    var.right_speed_km_h AS rightSpeedKmH
FROM video_metadata vm
LEFT JOIN video_analysis_result var ON vm.record_id = var.record_id
WHERE vm.user_id = #{userId}

    AND vm.create_time >= #{startDate}


    AND vm.create_time <= #{endDate}


    AND vm.type = #{actionType}


    AND vm.status = #{status}

ORDER BY


        vm.update_time


        vm.create_time




        ASC


        DESC


LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM video_metadata vm
LEFT JOIN video_analysis_result var ON vm.record_id = var.record_id
WHERE vm.user_id = #{userId}

    AND vm.create_time >= #{startDate}


    AND vm.create_time <= #{endDate}


    AND vm.type = #{actionType}


    AND vm.status = #{status}

SELECT
    DAY(create_time) AS day,
    COUNT(*) AS count
FROM video_metadata
WHERE user_id = #{userId}
AND YEAR(create_time) = #{year}
AND MONTH(create_time) = #{month}
GROUP BY DAY(create_time)
ORDER BY day
